const modal=document.querySelector("#bookingModal"),form=document.querySelector("#bookingForm"),panel=modal?.querySelector(".booking-panel");const names={swedish:"Swedish Massage",deep:"Deep Tissue Massage",beach:"Beach Massage",couples:"Couples Massage"};const staff="d9e27ab2-912e-42fc-86fc-2d935868f5e0";const sm=(id)=>`https://tranquilitasspa.setmore.com/book?products=${id}&staff=${staff}&staffSelected=false&step=additional-products&type=service`;const setmore={swedish:{label:"Swedish Massage",d60:{price:"$138",url:sm("286f0551-af67-4194-b2dd-39ef5b88a33d")},d90:{price:"$180",url:sm("ad4ffbf6-78ec-471d-a960-41b546ad5005")}},deep:{label:"Deep Tissue Massage",d60:{price:"$150",url:sm("d1acc957-60de-4e35-931d-067d7120bf55")},d90:{price:"$190",url:sm("53c6e182-db14-40d0-8402-3482c7b857f1")}},beach:{label:"Beach Massage",d60:{price:"$160",url:sm("27080f46-7544-4f6c-9689-223b3673a877")},d90:{price:"$200",url:sm("a526de37-539c-4830-b826-a1892695b9a1")}},couples:{label:"Couples Massage",d60:{price:"$280",url:sm("d67fea90-e066-4dfb-a748-967164579f91")},d90:{price:"$350",url:sm("4cd6abc0-385f-4784-a7e5-d1d61c8fdc8c")}}};function ensurePicker(){if(!panel||panel.querySelector(".setmore-picker"))return;const picker=document.createElement("section");picker.className="setmore-picker";picker.innerHTML=`<p class="eyebrow">BOOK ONLINE · SETMORE</p><h3>Choose your service.</h3><p class="setmore-note">Pick 60 or 90 minutes, then continue to our live Setmore calendar to choose your appointment time.</p><div class="setmore-grid">${Object.entries(setmore).map(([key,s])=>`<article class="setmore-card" data-setmore-service="${key}"><div><small>ST. LUCIA</small><h4>${s.label}</h4></div><div class="setmore-actions"><a href="${s.d60.url}"><span>60 MIN</span><strong>${s.d60.price}</strong></a><a href="${s.d90.url}"><span>90 MIN</span><strong>${s.d90.price}</strong></a></div></article>`).join("")}</div><button type="button" class="concierge-toggle">Special request, group, yacht or access issue?</button><p class="setmore-foot">Use the concierge form below only when you need something Setmore cannot handle directly.</p>`;panel.insertBefore(picker,form);if(form)form.hidden=true;const h=panel.querySelector(".booking-head h2");if(h)h.textContent="Book your St. Lucia massage";const p=panel.querySelector(".booking-head")?.nextElementSibling;if(p&&p.tagName==="P")p.textContent="Instant service booking is handled through Setmore. Custom requests can still come through our concierge form.";panel.querySelector(".concierge-toggle")?.addEventListener("click",e=>{if(!form)return;form.hidden=!form.hidden;e.currentTarget.textContent=form.hidden?"Special request, group, yacht or access issue?":"Hide concierge request form";if(!form.hidden)form.scrollIntoView({behavior:"smooth",block:"start"})})}function openBooking(service=null,duration=null){if(!modal)return;ensurePicker();modal.classList.add("open");document.body.style.overflow="hidden";panel?.querySelectorAll(".setmore-card").forEach(c=>c.classList.toggle("featured",!!service&&c.dataset.setmoreService===service));if(service&&form?.service)form.service.value=service;if(duration&&form?.duration)form.duration.value=duration;const target=service?panel?.querySelector(`[data-setmore-service="${service}"]`):panel?.querySelector(".setmore-picker");setTimeout(()=>target?.scrollIntoView({behavior:"smooth",block:"nearest"}),40)}function closeBooking(){if(!modal)return;modal.classList.remove("open");document.body.style.overflow=""}document.addEventListener("click",e=>{const b=e.target.closest("[data-book]");if(b){e.preventDefault();openBooking(b.dataset.service||null,b.dataset.duration||null)}if(e.target.matches("[data-close]")||e.target===modal)closeBooking()});document.addEventListener("keydown",e=>{if(e.key==="Escape")closeBooking()});document.querySelectorAll(".faq-q").forEach(b=>b.addEventListener("click",()=>b.parentElement.classList.toggle("open")));document.querySelectorAll(".pay-card").forEach(c=>c.addEventListener("click",()=>{document.querySelectorAll(".pay-card").forEach(x=>x.classList.remove("selected"));c.classList.add("selected");c.querySelector("input").checked=true}));if(form)form.addEventListener("submit",async e=>{e.preventDefault();const d=new FormData(form);const payload={service:d.get("service"),duration:d.get("duration"),date:d.get("date"),time:d.get("time"),location:d.get("location"),name:d.get("name"),phone:d.get("phone"),email:d.get("email"),payment:d.get("payment"),notes:d.get("notes")||"",website:d.get("website")||"",source:location.href};const btn=form.querySelector('button[type="submit"]'),old=btn.textContent;btn.disabled=true;btn.textContent="Sending request…";form.querySelectorAll(".booking-error").forEach(x=>x.remove());try{const r=await fetch("/api/booking-request",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});const data=await r.json();if(!r.ok)throw new Error(data.error||"Request failed");panel.innerHTML=`<div><p class="eyebrow">REQUEST RECEIVED</p><h2>We've got your St. Lucia massage request.</h2><p>A confirmation was sent to <strong>${payload.email}</strong>. Your request remains pending until therapist availability and property access are confirmed.</p><p><strong>Reference: ${data.reference}</strong></p><div class="success-summary"><div><span>Service</span><strong>${names[payload.service]||payload.service}</strong></div><div><span>Duration</span><strong>${payload.duration} minutes</strong></div><div><span>Date</span><strong>${payload.date}</strong></div><div><span>Time</span><strong>${payload.time}</strong></div><div><span>Location</span><strong>${payload.location}</strong></div><div><span>Payment</span><strong>${payload.payment==="pay"?"Pay online after confirmation":"Pay in person"}</strong></div></div><div style="margin-top:18px;background:#eef7f3;padding:16px">We will contact you to confirm therapist availability and any hotel, villa, yacht or beach access details.</div><button class="btn btn-dark" data-close style="margin-top:18px">Close</button></div>`}catch(ex){const box=document.createElement("div");box.className="booking-error";box.textContent="We couldn't send your request. Please try again or use the Need help button.";form.appendChild(box);btn.disabled=false;btn.textContent=old}});(()=>{const d=document.createElement("div");d.className="contact-dock";d.innerHTML='<div class="contact-menu" hidden><span>Need help booking?</span><a href="https://wa.me/12428168286" target="_blank" rel="noopener"><b>WhatsApp</b><small>Message our concierge</small></a><a href="sms:+12428168286"><b>iMessage / Text</b><small>+1 (242) 816-8286</small></a></div><button class="contact-trigger" aria-label="Open booking help">Need help?</button>';document.body.appendChild(d);const m=d.querySelector(".contact-menu"),b=d.querySelector(".contact-trigger");b.onclick=()=>m.hidden=!m.hidden})();